export function getNeighborhoodStats(name: string): GeoStats | undefined {
  const target = name.trim().toLowerCase();
  return HARTFORD_NEIGHBORHOOD_STATS.find((n) => n.name.toLowerCase() === target);
}

export function neighborhoodForTract(geoid: string): string | undefined {
  return TRACT_TO_NEIGHBORHOOD[geoid];
}
